import React, {Component, useState, useEffect} from "react";
import Config from "../scripts/config";
import { Link } from "react-router-dom";
import Empty from "./Empty";
import userEvent from "@testing-library/user-event";
import axios from "axios";
// import { useLocation } from 'react-router-dom';

const Map = props => {
    let ros = null;
    const [data, setData] = useState(false); // Lưu trữ dữ liệu từ server
    const [load, setLoading] = useState(false);
    const [message, setMessage] = useState('aaa'); // Trạng thái đang tải
    const [error, setError] = useState(null); // Lưu trữ lỗi (nếu có)
    const pollingInterval = Config.WAIT_ROBOTSTATE_TIMER;

    // const location = useLocation();
    // const {isSuccess} = location.state || {};

    useEffect(() => {
        // console.log("Dữ liệu từ bt callme", isSuccess);
        init_connection();
        view_map();

        let timeoutId; // Lưu ID của setTimeout để cleanup

        // Hàm gửi yêu cầu đến server
        const fetchData = async () => {
            try {
                setLoading(true); // Bắt đầu tải
                const response = await axios.get("http://" + Config.ROSBRIDGE_SERVER_IP + ":" + Config.SERVER_PORT + "/getstate")
                setData(response.data.data);
                setMessage(response.data.status);
                setError(null);
                setLoading(false);
                console.log("dữ liệu phản hồi từ server là:", response.data);

            } catch (err) {
                console.error('Error fetching data:', err);
                setError('Failed to fetch data');
                setLoading(false);
            } finally {
                // Đặt timeout để gọi lại fetchData sau pollingInterval
                timeoutId = setTimeout(fetchData, pollingInterval);
            }
        };

        // Bắt đầu polling
        fetchData();

        // Cleanup khi component bị unmount
        return () => clearTimeout(timeoutId);

    }, []);

    const init_connection = () => {

        ros = new window.ROSLIB.Ros();

        try{
            ros.connect(
                "ws://" + 
                Config.ROSBRIDGE_SERVER_IP +
                ":" + 
                Config.ROSBRIDGE_SERVER_PORT +
                ""
            );
        } catch (error) {
            console.log(
                "ws://" + Config.ROSBRIDGE_SERVER_IP + ":" + Config.ROSBRIDGE_SERVER_PORT + ""
            );
            console.log("connection problem");
        }

    }

    const view_map = () => {
        var viewer = new window.ROS2D.Viewer({
            divID: "nav_div",
            width: 960,
            height: 900,
        });

        var navClient = new window.NAV2D.OccupancyGridClientNav({
            ros: ros,
            rootObject: viewer.scene,
            viewer: viewer,
            severName: "/move_base",
            withOrientation: true,
        });
    }

    const handle_btConfirm = (event) => {
        event.preventDefault();
        console.log("Nut button confirm da duoc nhan")
    }

    return(
        <div className="map-container">

            <div>
                <Link to="/order" className="btn btn-info w-30 rounded-0" style={{ marginRight: '20px', marginBottom: '10px'}} >Order</Link>
                <buton className='btn btn-warning' onClick={handle_btConfirm} style={{ marginRight: '20px', marginBottom: '10px'}}>Confirm</buton>

                <label>
                    <span style={{ color: 'white', cursor: 'not-allowed', fontSize: '20px' }}>
                        {(() => {
                            if (data === 0) {
                                return 'Robot đang di chuyển tới điểm lấy hàng!!!';
                            } else if (data === 1) {
                                return 'Robot đã tới điểm lấy hàng!!!';
                            } else if (data === 2) {
                                return 'Robot đang di chuyển tới điểm trả hàng!!!';
                            } else if (data === 3) {
                                return 'Robot đã tới điểm trả hàng!!!';
                            }                       
                        })()}
                    </span> 
                </label>   

                {/* {data ? (
                    <label>
                        <span style={{ color: 'white', cursor: 'not-allowed', fontSize: '20px' }}>Robot đang di chuyển tới điểm đích!!!</span> 
                    </label>                                
                ) : (
                    <label>
                        <span style={{ color: 'white', cursor: 'not-allowed', fontSize: '20px' }}>Robot đã tới điểm đích!!!</span> 
                    </label> 
                )} */}
            </div>

            <h1 style={{ color: 'white' }} className="map_h1">MAP</h1>

            <div id="nav_div"></div>
        </div>
    );
}

export default Map;
